        .choice-item:active::after {
            animation: ripple 0.6s ease-out;
            background: radial-gradient(circle, rgba(235, 119, 248, 0.3) 0%, transparent 70%);
        }
        .choice-item .choice-text { 
            position: relative; z-index: 1; font-size: 1em; font-weight: 500; 
