        }
        .choice-item:hover .choice-text { 
            color: var(--accent-pink); transform: translateX(5px);
        }

        /* --- 控制按钮 & 字体面板 (样式保持，仅优化动画) --- */
        .controls-container { position: absolute; top: 12px; right: 12px; display: flex; gap: 10px; z-index: 10; }
        .control-btn { 
            width: 32px; height: 32px; 
            background: linear-gradient(135deg, var(--bg-light) 0%, var(--bg-medium) 100%);
            border-radius: 50%; cursor: pointer; display: flex; justify-content: center; align-items: center; 
            border: 2px solid var(--border-color); 
            transition: all 0.3s var(--ease-in-out-cubic); /* 优化缓动 */
            box-shadow: 0 3px 10px rgba(0,0,0,0.3); position: relative; overflow: hidden;
        }
        .control-btn::before {
            content: ''; position: absolute; top: 50%; left: 50%; width: 0; height: 0;
            background: radial-gradient(circle, var(--accent-purple) 0%, transparent 70%);
            border-radius: 50%; transform: translate(-50%, -50%);
            transition: width 0.4s ease, height 0.4s ease; opacity: 0.5;
        }
        .control-btn:hover::before { width: 60px; height: 60px; }
        .control-btn:hover { 
            transform: scale(1.1); /* 减小悬停缩放幅度 */
            box-shadow: var(--glow-purple);
        }
        #theme-switcher:hover { transform: scale(1.1) rotate(180deg); } /* 减小悬停缩放幅度 */
        #font-switcher:hover .font-icon { animation: fontIconRotate 0.5s ease; }
        .control-icon { font-size: 18px; transition: transform 0.4s var(--ease-in-out-cubic); filter: drop-shadow(0 0 3px currentColor); position: relative; z-index: 1; }
        body.theme-light #theme-icon { transform: rotate(360deg); }
        .font-icon { font-size: 16px; font-weight: bold; color: var(--accent-purple); filter: drop-shadow(0 0 3px currentColor); }
        .hidden { display: none !important; }

        .font-panel {
            position: absolute; top: 50px; right: 12px;
            background-color: var(--bg-medium); border-radius: 10px; padding: 10px;
            width: 180px; box-shadow: var(--border-shadow); backdrop-filter: blur(10px);
            border: 1px solid var(--border-color); z-index: 20;
            animation: fadeIn 0.3s var(--ease-out-quint);
            display: flex; flex-direction: column; gap: 8px;
        }
        .font-panel::before {
            content: ''; position: absolute; top: -8px; right: 25px; width: 16px; height: 16px;
            background: var(--bg-medium); transform: rotate(45deg);
            border-top: 1px solid var(--border-color); border-left: 1px solid var(--border-color);
        }
        .font-option {
            padding: 8px; border-radius: 6px; cursor: pointer;
            transition: all 0.3s var(--ease-out-quint);
        }
        .font-option:hover { background-color: var(--bg-light); transform: translateX(-3px); }
        .font-sample { font-size: 1.1em; font-weight: 500; color: var(--accent-pink); }
        .font-desc { font-size: 0.8em; color: var(--text-secondary); margin-top: 3px; }

        /* --- 性能与响应式 --- */
        .choice-item, .rumor-card, .view-switcher-btn, .control-btn, .page-container {
            will-change: transform, opacity;
        }
        @media (max-width: 768px) {
            .choices-title::before { left: 10%; }
            .choices-title::after { right: 10%; }
            .view-switcher-btn { padding: 8px 20px; font-size: 0.85em; }
            .choice-item { padding: 12px 15px; }
            .controls-container { gap: 8px; }
            .control-btn { width: 28px; height: 28px; }
            .control-icon { font-size: 16px; }
            .font-icon { font-size: 14px; }
            .font-panel { right: 8px; width: 160px; }
            .font-panel::before { right: 20px; }
            body { -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; text-rendering: optimizeLegibility; }
        }
    </style>
</head>
<body class="font-modern">
    <!-- HTML结构保持不变 -->
    <main id="main-card">
        <div class="controls-container">
