        </div>
        <div id="main-content-page" class="page-container">
            <section class="content-section">
                <strong>~♡ 背德之路 ♡~</strong>
                <div class="content-text" id="content-text">$1</div>
            </section>
            <div class="general-info-section" id="general-info-section">
                <div class="info-row" id="diary-row"><strong>📝 少女想法:</strong><span class="content diary-content" id="diary-content">$2</span></div>
                 <div class="info-row" id="summary-row"><strong>📜 心情摘要:</strong><span class="content summary-content" id="summary-content">$3</span></div>
            </div>
        </div>
        <div id="rumors-page" class="page-container rumors-page hidden">
            <div class="rumor-card" id="rumor-neighbor"><strong >街坊邻里:</strong><p>$7</p></div>
            <div class="rumor-card" id="rumor-colleague"><strong>公司同事:</strong><p>$8</p></div>
            <div class="rumor-card" id="rumor-student"><strong>女儿的同学:</strong><p>$9</p></div>
