    <script>
        (function() {
            // SillyTavern核心功能和大部分逻辑保持不变
            const triggerQuickReply = (text) => { if (!text || ['…', '...'].includes(text.trim()) || text.trim().length === 0) return; if (typeof triggerSlash === 'function') triggerSlash(`/send ${text}|/trigger`); };
            const hasContent = (element) => element && element.innerText && !['…', '...'].includes(element.innerText.trim()) && element.innerText.trim().length > 0;
            const setupChoiceListeners = () => { 
                document.getElementById('choices-section')?.addEventListener('click', (event) => { 
                    const item = event.target.closest('.choice-item'); 
                    if (item) {
                        item.style.transform = 'scale(0.98)'; // 轻微的点击反馈
                        setTimeout(() => { item.style.transform = ''; }, 150);
                        triggerQuickReply(item.querySelector('.choice-text')?.innerText); 
                    }
                }); 
            };
            const processDialogues = () => { 
                const contentText = document.getElementById('content-text'); 
                if (contentText?.innerText) { 
                    const regex = /"([^"]+)"|"([^"]+)"|'([^']+)'|「([^」]+)」|『([^』]+)』/g; 
                    contentText.innerHTML = contentText.innerText.replace(regex, `<span class="dialog-text">$&</span>`).split('\\n').map(p => `<p>${p || '&nbsp;'}</p>`).join(''); 
                } 
            };
            const hideEmptyElements = () => {
                const checks = [
                    ['diary-content', 'diary-row'], ['summary-content', 'summary-row'],
                    ['choice-1', 'choice-1'], ['choice-2', 'choice-2'], ['choice-3', 'choice-3'],
                    ['rumor-neighbor > p', 'rumor-neighbor'], ['rumor-colleague > p', 'rumor-colleague'],
                    ['rumor-student > p', 'rumor-student'], ['rumor-teacher > p', 'rumor-teacher']
                ];
                checks.forEach(([contentSel, containerId]) => {
                    const container = document.getElementById(containerId);
                    if (container) {
                         const content = container.id.startsWith('choice-') ? container.querySelector('.choice-text') : document.querySelector(`#${contentSel}`);
                         if (!hasContent(content)) container.style.display = 'none';
                    }
                });
                if (!hasContent(document.getElementById('diary-content')) && !hasContent(document.getElementById('summary-content'))) { document.getElementById('general-info-section').style.display = 'none'; }
                if (Array.from(document.querySelectorAll('.choice-item')).every(item => item.style.display === 'none')) { document.getElementById('choices-section').style.display = 'none'; }
                if(Array.from(document.querySelectorAll('.rumor-card')).every(card => card.style.display === 'none')) { document.querySelector('.view-switcher-container').style.display = 'none'; }
            };
            const setupThemeSwitcher = () => { /* 逻辑不变 */
                const switcher = document.getElementById('theme-switcher'), icon = document.getElementById('theme-icon'), body = document.body, savedTheme = localStorage.getItem('apex_theme_v9_2');
                const applyTheme = (theme) => { 
                    body.classList.toggle('theme-light', theme === 'light'); 
                    icon.textContent = theme === 'light' ? '☀️' : '🌙'; 
                };
                applyTheme(savedTheme);
                switcher.addEventListener('click', () => { 
                    const newTheme = body.classList.contains('theme-light') ? 'dark' : 'light'; 
                    applyTheme(newTheme); 
                    localStorage.setItem('apex_theme_v9_2', newTheme); 
                });
            };
            const setupFontSwitcher = () => { /* 逻辑不变 */
                const fontSwitcher = document.getElementById('font-switcher');
                const fontPanel = document.getElementById('font-panel');
                const fontClasses = ['font-modern', 'font-classic', 'font-playful', 'font-elegant', 'font-tech'];
                const fontClassToChar = { 'font-modern': '现', 'font-classic': '经', 'font-playful': '活', 'font-elegant': '雅', 'font-tech': '科' };
                const savedFont = localStorage.getItem('apex_font_v1') || 'font-modern';
                const applyFont = (fontClass) => {
                    document.body.classList.remove(...fontClasses);
                    document.body.classList.add(fontClass);
                    localStorage.setItem('apex_font_v1', fontClass);
                    fontSwitcher.querySelector('.font-icon').textContent = fontClassToChar[fontClass] || '字';
                };
                applyFont(savedFont);
                fontSwitcher.addEventListener('click', (e) => { e.stopPropagation(); fontPanel.classList.toggle('hidden'); });
                fontPanel.querySelectorAll('.font-option').forEach(option => {
                    option.addEventListener('click', () => {
                        const fontClass = option.getAttribute('data-font-class');
                        applyFont(fontClass);
                        option.style.transform = 'scale(0.95)';
                        setTimeout(() => { option.style.transform = ''; }, 150);
                    });
                });
                document.addEventListener('click', (e) => {
                    if (!fontPanel.classList.contains('hidden') && !fontSwitcher.contains(e.target) && !fontPanel.contains(e.target)) {
                        fontPanel.classList.add('hidden');
                    }
                });
            };

            const setupViewSwitcher = () => {
                const mainPage = document.getElementById('main-content-page');
                const rumorsPage = document.getElementById('rumors-page');
                const btnMain = document.getElementById('switch-to-main');
                const btnRumors = document.getElementById('switch-to-rumors');
                const mainCard = document.getElementById('main-card');

                const switchAndScroll = (showPage, hidePage, activateBtn, deactivateBtn) => {
                    hidePage.classList.add('fade-out');

                    // --- 关键修改 ---
                    // 将setTimeout的延迟从400ms修改为350ms，与CSS中的transition-duration保持一致
                    // 这是确保动画流畅、无闪烁，并且滚动功能正常的关键。
                    setTimeout(() => {
                        hidePage.classList.add('hidden');
                        hidePage.classList.remove('fade-out');

                        showPage.classList.remove('hidden');
                        // 使用一个微小的延迟来确保display属性生效后再开始入场动画
                        requestAnimationFrame(() => {
                            showPage.classList.add('fade-in');
                        });

                        // 在动画结束前就可以移除类，因为最终状态已确定
                        setTimeout(() => {
                            showPage.classList.remove('fade-in');
                        }, 350);

                        activateBtn.classList.add('active');
                        deactivateBtn.classList.remove('active');

                        // 滚动到顶部的逻辑保持不变，确保功能正常
                        setTimeout(() => {
                            mainCard.scrollIntoView({ behavior: 'smooth', block: 'start' });
                            window.scrollTo({ top: 0, behavior: 'smooth' });
                            if ('ontouchstart' in window) {
                                document.body.scrollTop = 0;
                                document.documentElement.scrollTop = 0;
                            }
                        }, 50); // 稍微提前滚动时机，感觉更流畅
                    }, 350); // 必须与CSS动画时长匹配
                };

                btnMain.addEventListener('click', () => {
                    if (mainPage.classList.contains('hidden')) {
                        switchAndScroll(mainPage, rumorsPage, btnMain, btnRumors);
                    }
                });
                btnRumors.addEventListener('click', () => {
                    if (rumorsPage.classList.contains('hidden')) {
                        switchAndScroll(rumorsPage, mainPage, btnRumors, btnMain);
                    }
                });
            };

            document.addEventListener('DOMContentLoaded', () => { 
                setupChoiceListeners(); 
                processDialogues(); 
                setupThemeSwitcher(); 
                setupFontSwitcher(); 
                setupViewSwitcher(); 
                hideEmptyElements(); 

                if ('ontouchstart' in window) {
                    document.body.style.webkitFontSmoothing = 'antialiased';
                    document.body.style.textRendering = 'optimizeLegibility';
                }
            });
        })();
    </script>
</body>
</html>
